    .eyebrow {
      display: inline-flex;
      width: fit-content;
      align-items: center;
      gap: 0.5rem;
      border: 1px solid rgba(217, 111, 61, 0.25);
      border-radius: 999px;
      background: var(--accent-soft);
      color: #793716;
