    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      max-width: 11ch;
      margin-bottom: 1rem;
      font-size: clamp(3rem, 8vw, 6.6rem);
      letter-spacing: -0.085em;
      line-height: 0.9;
    }

    .hero-copy p {
      max-width: 40rem;
      color: var(--muted);
      font-size: clamp(1.05rem, 2vw, 1.25rem);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      margin-top: 1rem;
    }

    .hero-panel {
      display: grid;
      gap: 1rem;
    }

    .showcase-card,
    .metric-card {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      box-shadow: 0 18px 46px rgba(23, 32, 27, 0.1);
    }

    .showcase-card {
      display: grid;
      min-height: 22rem;
      align-content: end;
      background:
        radial-gradient(circle at 30% 25%, #f0b987 0 5rem, transparent 5.1rem),
        radial-gradient(circle at 72% 34%, #cddbd3 0 7rem, transparent 7.1rem),
        linear-gradient(150deg, #f9efe4, #dfd5c6);
      padding: 1.1rem;
    }

    .product-orb {
      width: min(80%, 19rem);
      aspect-ratio: 1;
      margin: 1rem auto 0;
      border-radius: 42% 58% 48% 52%;
      background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.5), transparent 40%),
        linear-gradient(135deg, #315947, #88a392);
      box-shadow: inset -24px -32px 60px rgba(23, 32, 27, 0.22), 0 24px 50px rgba(23, 32, 27, 0.2);
    }

    .showcase-info {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      border-radius: 1.3rem;
      background: rgba(255, 255, 255, 0.74);
      padding: 1rem;
      backdrop-filter: blur(16px);
    }

    .showcase-info h2 {
      margin-bottom: 0.15rem;
      font-size: 1.15rem;
    }

    .price {
      font-weight: 900;
    }

    .metric-card {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1px;
      background: var(--border);
    }

    .metric {
      background: var(--surface);
      padding: 1.15rem;
    }

    .metric strong {
      display: block;
      font-size: 1.55rem;
      letter-spacing: -0.04em;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.9rem;
    }

    section {
      padding: 3rem 0;
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.4rem;
    }

    .section-heading h2 {
      margin-bottom: 0.2rem;
      font-size: clamp(2rem, 4vw, 3.1rem);
      letter-spacing: -0.065em;
      line-height: 1;
    }

    .section-heading p {
      max-width: 38rem;
      margin-bottom: 0;
      color: var(--muted);
    }

    .category-tabs {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-bottom: 1.3rem;
    }

    .tab-button {
      border: 1px solid var(--border);
      border-radius: 999px;
      background: #ffffff;
      color: var(--muted);
      font-weight: 800;
      padding: 0.68rem 0.95rem;
    }

    .tab-button[aria-selected="true"] {
      border-color: var(--brand);
      background: var(--brand);
      color: #ffffff;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .deal-card,
    .editorial-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
      box-shadow: 0 14px 32px rgba(23, 32, 27, 0.08);
    }

    .product-card {
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    .product-art {
      display: grid;
      min-height: 13rem;
      place-items: center;
      background: var(--product-bg, #eee5d8);
    }

    .product-art span {
      width: 7rem;
      aspect-ratio: 1;
      border-radius: 35% 65% 48% 52%;
      background: var(--product-color, var(--brand));
      box-shadow: inset -18px -20px 34px rgba(23, 32, 27, 0.18), 0 18px 32px rgba(23, 32, 27, 0.14);
    }

    .product-body {
      display: flex;
      flex: 1;
      flex-direction: column;
      padding: 1rem;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 700;
    }

    .product-body h3 {
      margin: 0.5rem 0 0.3rem;
      font-size: 1.08rem;
      letter-spacing: -0.03em;
    }

    .product-body p {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.8rem;
      margin-top: auto;
    }

    .add-button {
      border: 0;
      border-radius: 999px;
      background: var(--ink);
      color: #ffffff;
      font-weight: 800;
      padding: 0.68rem 0.9rem;
    }

    .add-button:hover,
    .add-button:focus-visible {
      background: var(--brand);
      outline: none;
    }

    .deals-layout {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: 1rem;
    }

    .deal-card {
      overflow: hidden;
      padding: clamp(1.3rem, 4vw, 2rem);
    }

    .deal-card.featured {
      display: grid;
      grid-template-columns: 1fr 0.85fr;
      gap: 1.5rem;
      align-items: center;
      background:
        radial-gradient(circle at 86% 24%, rgba(255, 255, 255, 0.55), transparent 12rem),
        linear-gradient(135deg, #2f5748, #1c3029);
      color: #ffffff;
    }

    .deal-card.featured p {
      color: rgba(255, 255, 255, 0.76);
    }

    .deal-card h3 {
      margin-bottom: 0.45rem;
      font-size: clamp(1.65rem, 4vw, 3rem);
      letter-spacing: -0.065em;
      line-height: 1;
    }

    .deal-code {
      display: inline-flex;
      margin: 0.75rem 0 1rem;
      border: 1px dashed rgba(255, 255, 255, 0.52);
      border-radius: 999px;
      padding: 0.45rem 0.7rem;
      font-weight: 900;
      letter-spacing: 0.08em;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.65rem;
      max-width: 21rem;
      margin: 1.2rem 0;
    }

    .countdown div {
      border-radius: 1rem;
      background: rgba(255, 255, 255, 0.14);
      padding: 0.75rem;
      text-align: center;
    }

    .countdown strong {
      display: block;
      font-size: 1.55rem;
      line-height: 1;
    }

    .countdown span {
      color: rgba(255, 255, 255, 0.72);
      font-size: 0.78rem;
      font-weight: 800;
      text-transform: uppercase;
    }

    .deal-visual {
      min-height: 18rem;
      border-radius: 2rem;
      background:
        radial-gradient(circle at 45% 42%, #eab17f 0 4rem, transparent 4.1rem),
        radial-gradient(circle at 62% 58%, #fff2df 0 6rem, transparent 6.1rem),
        linear-gradient(145deg, rgba(255, 255, 255, 0.24), rgba(255, 255, 255, 0.06));
    }

    .deal-stack {
      display: grid;
      gap: 1rem;
    }

    .mini-deal {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .mini-deal p {
      margin-bottom: 0;
      color: var(--muted);
    }

    .discount {
      flex: 0 0 auto;
      border-radius: 1rem;
      background: var(--accent-soft);
      color: #793716;
      font-size: 1.45rem;
      font-weight: 900;
      padding: 0.8rem 0.9rem;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.2fr repeat(2, 0.9fr);
      gap: 1rem;
    }

    .editorial-card {
      display: flex;
      min-height: 24rem;
      flex-direction: column;
      justify-content: end;
      overflow: hidden;
      background: var(--editorial-bg, #ede5d8);
    }

    .editorial-card.large {
      min-height: 31rem;
    }

    .editorial-art {
      flex: 1;
      min-height: 11rem;
      background:
        radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.72) 0 5rem, transparent 5.1rem),
        radial-gradient(circle at 70% 45%, rgba(23, 32, 27, 0.12) 0 4rem, transparent 4.1rem);
    }

    .editorial-body {
      border-top: 1px solid rgba(255, 255, 255, 0.38);
      background: rgba(255, 255, 255, 0.7);
      padding: 1.2rem;
      backdrop-filter: blur(18px);
    }

    .editorial-body span {
      color: var(--brand);
      font-size: 0.78rem;
      font-weight: 900;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .editorial-body h3 {
      margin: 0.35rem 0;
      font-size: 1.35rem;
      letter-spacing: -0.04em;
      line-height: 1.08;
    }

    .newsletter {
      display: grid;
      grid-template-columns: 1fr 0.9fr;
      gap: 1rem;
      align-items: center;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background:
        radial-gradient(circle at 86% 26%, rgba(217, 111, 61, 0.18), transparent 16rem),
        #ffffff;
      padding: clamp(1.4rem, 4vw, 2.2rem);
      box-shadow: var(--shadow);
    }

    .newsletter h2 {
      margin-bottom: 0.5rem;
      font-size: clamp(2rem, 4vw, 3.2rem);
      letter-spacing: -0.065em;
      line-height: 1;
    }

    .newsletter p {
      margin-bottom: 0;
      color: var(--muted);
    }

    .signup-form {
      display: flex;
      gap: 0.6rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: var(--bg);
      padding: 0.35rem;
    }

    .signup-form label {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
    }

    .signup-form input {
      min-width: 0;
      flex: 1;
      border: 0;
      background: transparent;
      padding: 0.8rem 1rem;
      color: var(--ink);
    }

    .signup-form input:focus {
      outline: none;
    }

    .form-message {
      min-height: 1.5rem;
      margin-top: 0.65rem;
      color: var(--brand);
      font-weight: 800;
    }

    .site-footer {
      margin-top: 3rem;
      border-top: 1px solid var(--border);
      background: #ffffff;
    }

    .footer-content {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.5rem 0;
      color: var(--muted);
    }

    .footer-links {
      display: flex;
      gap: 1rem;
      font-weight: 700;
    }

    :focus-visible {
      outline: 3px solid rgba(217, 111, 61, 0.55);
      outline-offset: 3px;
    }

    @media (max-width: 920px) {
      .hero,
      .deals-layout,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .editorial-card.large {
        grid-column: 1 / -1;
      }
    }

    @media (max-width: 700px) {
      .nav {
        align-items: flex-start;
      }

      .nav-links {
        display: none;
      }

      .header-actions .secondary-button {
        display: none;
      }

      .hero {
        padding-top: 2rem;
      }

      .hero-copy {
        min-height: auto;
      }

      .section-heading {
        align-items: start;
        flex-direction: column;
      }

      .product-grid,
      .editorial-grid,
      .deal-card.featured {
        grid-template-columns: 1fr;
      }

      .metric-card {
        grid-template-columns: 1fr;
      }

      .signup-form {
        align-items: stretch;
        flex-direction: column;
        border-radius: var(--radius-md);
      }

      .signup-form .primary-button {
        width: 100%;
      }

      .footer-content {
        align-items: flex-start;
        flex-direction: column;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header class="site-header">
